         }
@@ -612,13 +612,21 @@ public class OozieDBCLI {
             }
             ResultSet rs = statement.executeQuery(getSelectQuery(tableName, columnNames));
             while (rs.next()) {
-                for (int i = 0; i < columnNames.size(); i++) {
-                    Clob confClob = rs.getClob(columnNames.get(i));
